    const savedOrder = Array.isArray(readerSettings.btnOrder) ? readerSettings.btnOrder.filter((id) => canonicalOrder.includes(id)) : [];
    const order = savedOrder.concat(canonicalOrder.filter((id) => !savedOrder.includes(id)));

