    if (align === 'center') {
        element.style.textAlign = 'center';
        element.style.textIndent = '';
    } else if (align === 'indent') {
        element.style.textAlign = 'left';
        element.style.textIndent = '2em';
    } else if (align === 'left') {
        element.style.textAlign = 'left';
        element.style.textIndent = '';
    } else {
        element.style.textAlign = '';
        element.style.textIndent = '';
    }
